import React from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import {
  IconShield,
  IconMail,
  IconPhone,
  IconMapPin,
  IconBriefcaseFull,
  IconPeople,
  IconEye,
  IconLock,
  IconRobot,
  IconPrivacy
} from '../Icons';

const Footer = () => {
  const { darkMode } = useAuth();

  const bg = darkMode ? '#0F172A' : '#0F172A';
  const border = '#1E293B';
  const muted = '#64748B';
  const light = '#94A3B8';

  return (
    <footer style={{ background: bg, borderTop: `1px solid ${border}`, padding: '48px 40px 24px', fontFamily: 'Inter, sans-serif' }}>
      <div style={{ maxWidth: '1200px', margin: '0 auto' }}>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '40px', marginBottom: '40px' }}>

          {/* Brand */}
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '16px' }}>
              <img src="/images/pose1.png" alt="Kiba" style={{ width: '32px', height: '32px', objectFit: 'contain' }} onError={e => e.target.style.display = 'none'} />
              <span style={{ color: '#FFD60A', fontWeight: 900, fontSize: '18px', letterSpacing: '-0.5px' }}>
                Kibali<span style={{ color: '#00B4D8' }}>Guard</span>
              </span>
            </div>
            <p style={{ fontSize: '13px', color: light, lineHeight: 1.8, marginBottom: '16px', maxWidth: '240px' }}>
              Apply with confidence. Your data stays yours. Kenya Data Protection Act 2019 compliant recruitment platform.
            </p>
            <div style={{ display: 'flex', gap: '8px' }}>
              <div style={{ width: '36px', height: '36px', borderRadius: '10px', background: '#1E293B', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <IconShield color="#00B4D8" size={16} />
              </div>
              <div style={{ width: '36px', height: '36px', borderRadius: '10px', background: '#1E293B', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <IconLock color="#10B981" size={16} />
              </div>
              <div style={{ width: '36px', height: '36px', borderRadius: '10px', background: '#1E293B', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <IconEye color="#FFB703" size={16} />
              </div>
            </div>
          </div>

          {/* For Job Seekers */}
          <div>
            <h4 style={{ color: '#fff', fontWeight: 800, fontSize: '14px', marginBottom: '16px', textTransform: 'uppercase', letterSpacing: '0.5px' }}>For Job Seekers</h4>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              {[
                { to: '/', label: 'Browse Jobs', Icon: IconBriefcaseFull },
                { to: '/register', label: 'Create Account', Icon: IconPeople },
                { to: '/talent-pool', label: 'Talent Pool', Icon: IconPeople },
                { to: '/privacy-centre', label: 'Privacy Centre', Icon: IconPrivacy },
                { to: '/access-logs', label: 'Who Saw My Docs', Icon: IconEye },
                { to: '/chat', label: 'Ask Kiba', Icon: IconRobot },
              ].map(item => (
                <Link key={item.to + item.label} to={item.to} style={{ display: 'flex', alignItems: 'center', gap: '8px', color: light, textDecoration: 'none', fontSize: '13px', fontWeight: 500, transition: 'color 0.2s' }}
                  onMouseEnter={e => e.currentTarget.style.color = '#FFD60A'}
                  onMouseLeave={e => e.currentTarget.style.color = light}>
                  <item.Icon color={muted} size={14} />
                  {item.label}
                </Link>
              ))}
            </div>
          </div>

          {/* For Employers */}
          <div>
            <h4 style={{ color: '#fff', fontWeight: 800, fontSize: '14px', marginBottom: '16px', textTransform: 'uppercase', letterSpacing: '0.5px' }}>For Employers</h4>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              {[
                { to: '/register', label: 'Register as HR Staff', Icon: IconPeople },
                { to: '/staff', label: 'Post a Job', Icon: IconBriefcaseFull },
                { to: '/staff', label: 'Review Applications', Icon: IconEye },
                { to: '/staff', label: 'Request Document Access', Icon: IconLock },
              ].map((item, i) => (
                <Link key={i} to={item.to} style={{ display: 'flex', alignItems: 'center', gap: '8px', color: light, textDecoration: 'none', fontSize: '13px', fontWeight: 500, transition: 'color 0.2s' }}
                  onMouseEnter={e => e.currentTarget.style.color = '#FFD60A'}
                  onMouseLeave={e => e.currentTarget.style.color = light}>
                  <item.Icon color={muted} size={14} />
                  {item.label}
                </Link>
              ))}
            </div>
          </div>

          {/* Contact */}
          <div>
            <h4 style={{ color: '#fff', fontWeight: 800, fontSize: '14px', marginBottom: '16px', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Contact</h4>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              {[
                { Icon: IconMail, text: 'odhiambocheryl10@gmail.com' },
                { Icon: IconPhone, text: '+254 712 345 678' },
                { Icon: IconMapPin, text: 'Nairobi, Kenya' },
              ].map((item, i) => (
                <div key={i} style={{ display: 'flex', alignItems: 'flex-start', gap: '10px' }}>
                  <div style={{ flexShrink: 0, marginTop: '2px' }}>
                    <item.Icon color="#00B4D8" size={15} />
                  </div>
                  <span style={{ fontSize: '13px', color: light, lineHeight: 1.5 }}>{item.text}</span>
                </div>
              ))}
            </div>

            <div style={{ marginTop: '20px' }}>
              <div style={{ background: '#1E293B', borderRadius: '12px', padding: '14px 16px', border: '1px solid #334155' }}>
                <p style={{ fontSize: '12px', color: '#94A3B8', lineHeight: 1.6, margin: 0 }}>
                  <span style={{ color: '#FFD60A', fontWeight: 700 }}>KDPA 2019 Compliant</span><br />
                  All data processing on KibaliGuard is governed by the Kenya Data Protection Act 2019. Your rights are technically enforced, not just written in a policy.
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* Bottom bar */}
        <div style={{ borderTop: `1px solid ${border}`, paddingTop: '24px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px' }}>
          <div>
            <p style={{ fontSize: '12px', color: muted, margin: 0 }}>
              2026 KibaliGuard. Built by Cheryl Atieno Odhiambo · Zetech University
            </p>
            <p style={{ fontSize: '11px', color: '#475569', margin: '4px 0 0' }}>
              Cheryl Kreativ Studio · Diploma in ICT · Supervisor: Mr. Mutuku Francis
            </p>
          </div>
          <div style={{ display: 'flex', gap: '16px', flexWrap: 'wrap' }}>
            {[
              { to: '/register', label: 'Privacy Policy' },
              { to: '/register', label: 'Terms of Use' },
              { to: '/register', label: 'Data Rights' },
            ].map((item, i) => (
              <Link key={i} to={item.to} style={{ fontSize: '12px', color: muted, textDecoration: 'none', transition: 'color 0.2s' }}
                onMouseEnter={e => e.currentTarget.style.color = '#00B4D8'}
                onMouseLeave={e => e.currentTarget.style.color = muted}>
                {item.label}
              </Link>
            ))}
          </div>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
